        print('---')
EOF", "summary": "Inspect one latest doc detailed content"}

{"command": "python3 << 'EOF'
import json
d = json.load(open('/root/DATA/products/CoachForce.json'))
# check slack structure
slack = d['slack']
print("slack type:", type(slack), "top-level:", list(slack.keys()) if isinstance(slack, dict) else len(slack))
if isinstance(slack, dict):
    for k in list(slack.keys())[:5]:
        print(" channel:", k)
elif isinstance(slack, list):
    for m in slack[:3]:
        print(m)
print()
print("meeting_transcripts type:", type(d['meeting_transcripts']))
if isinstance(d['meeting_transcripts'], list):
    print(" count:", len(d['meeting_transcripts']))
    for mt in d['meeting_transcripts'][:2]:
        print(" keys:", list(mt.keys()))
        for k,v in mt.items():
            if k != 'transcript':
                print(f"   {k}: {str(v)[:200]}")
EOF", "summary": "Inspect slack and meetings structure"}

{"command": "python3 << 'EOF'
import json
d = json.load(open('/root/DATA/products/CoachForce.json'))
# Meeting transcript for Market Research Report
for mt in d['meeting_transcripts']:
    if mt['document_type']=='Market Research Report':
        print("Meeting:", mt['id'], "date:", mt['date'])
        print("Participants:", mt['participants'])
        print("Transcript type:", type(mt['transcript']))
        if isinstance(mt['transcript'], list):
            for t in mt['transcript']:
                print(t)
        else:
            print(mt['transcript'][:3000])
EOF", "summary": "Show market research report meeting transcript"}

{"command": "python3 << 'EOF'
import json
d = json.load(open('/root/DATA/products/CoachForce.json'))
# Find slack message about market research report
for m in d['slack']:
    text = m['Message']['User']['text']
    if 'market_research' in text.lower() or 'market research' in text.lower():
        print(m['id'], '|', m['Message']['User']['userId'], '|', text[:250])
        if m.get('ThreadReplies'):
            for r in m['ThreadReplies']:
                print('   REPLY:', r['User']['userId'], '|', r['User']['text'][:250])
        print()
EOF", "summary": "Find slack messages about market research report"}

